  "probability": 0.04,
  "range_low": 0.02,
  "range_high": 0.08,
  "summary": [
    "Anchor is the historical likelihood of a 2/3 majority under the post-2014 199-seat system.",
    "Upside drivers include seat-share forecasts near the two-thirds threshold and structural electoral bias favoring cohesive majorities.",
    "Downside signals include dispersed polls, three-party Parliament dynamics, and market expectations of regime change.",
    "Calibrated posterior probability is 4% with an intentionally wide uncertainty range."
  ],
  "confidence": "low",
  "narrative": "Starting from a baseline anchored in historical two-thirds outcomes under Hungary's current 199-seat system, we apply updates from both structural advantages for a cohesive bloc and current political uncertainty. The net effect of mixed polls, fragmentation, and market signals reduces the odds to a low posterior of about 4%, with substantial uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class is the historical likelihood of a 2/3 majority under the post-2014 199-seat system; anchor probability chosen as a plausible baseline prior to applying updates."
    },
    "factor_updates": [
      {
        "factor": "Seat-share forecasts near two-thirds for Fidesz-KDNP (Real-PR projection ~64% of seats)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Seat-based projections indicating around two-thirds of seats for Fidesz-KDNP increase the plausibility of a 133+ seat result under the 199-seat system."
      },
      {
        "factor": "Electoral-system bias under the post-2014 framework (199 seats, 106 SMD, 93 PR)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Structural features amplify incumbents when votes cohere, increasing the chances of a 2/3 majority under cohesive support."
      },
      {
        "factor": "Historical precedent of 2/3 majorities under the current framework",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Past occurrences demonstrate that a 2/3 outcome is possible within the current system, providing a baseline for expectation."
      },
      {
        "factor": "Opposition polling gains and three-party fragmentation",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Strong opposition performance and fragmentation reduce the likelihood that a single bloc can secure 133+ seats."
      },
      {
        "factor": "Prediction markets indicating substantial odds of opposition victory",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Markets signaling a non-trivial chance of regime change lower the probability of a 2/3 majority for the incumbent."
      },
      {
        "factor": "Market commentary linking regime change to weaker odds of a 2/3 majority for the ruling bloc",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Financial commentary implies that a 2/3 majority is less likely when regime-change risk is priced in."
      },
      {
        "factor": "Opposition unification behind Tisza",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation increases the probability that a non-Fidesz bloc captures 133+ seats if the swing concentrates."
      },
      {
        "factor": "Electoral boundary changes amplifying the largest party's seat share",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Redistricting can disproportionately aid the leading bloc under the current rules."
      }
    ],
    "synthesis_rationale": "A cautious aggregation of upside and downside updates, with attention to potential correlations (e.g., markets and polls), yields a low posterior of 4%. The combination of structural advantages for a cohesive bloc and clear countervailing signals from polls, fragmentation, and regime-change expectations justifies a conservative, wide-calibration estimate rather than a high-confidence forecast."
  }
}

